  const [hoveredBattlefieldParticipantId, setHoveredBattlefieldParticipantId] = useState<number | null>(null);
  const [onlineUserIds, setOnlineUserIds] = useState<Set<number>>(new Set());
  const [selectedPlayersToInvite, setSelectedPlayersToInvite] = useState<number[]>([]);
  const [inviteTeamName, setInviteTeamName] = useState<string>('');
  const [inviteTeamMode, setInviteTeamMode] = useState<'existing' | 'new'>('existing');
  const [inviteTeamSelection, setInviteTeamSelection] = useState<string>('');
  const [newParticipantData, setNewParticipantData] = useState({
    type: 'player' as 'player' | 'dm',
    team: '',
    selectedPlayerArmies: [] as number[],
    tempArmyName: '',
    tempArmyCategory: 'Swordsmen' as string,
    tempArmyTroops: 100,
    tempArmyStats: {
      equipment: 5,
      discipline: 5,
      morale: 5,
      command: 5,
      logistics: 5
    }
  });
  const [newParticipantTeamMode, setNewParticipantTeamMode] = useState<'existing' | 'new'>('existing');
  const [newParticipantTeamSelection, setNewParticipantTeamSelection] = useState<string>('');

  // Helper function to get correct image URL (handles both data URLs from DB and file paths)
  const getImageUrl = (imageUrl: string | undefined): string | undefined => {
    if (!imageUrl) return undefined;
    // Data URLs — return as-is
    if (imageUrl.startsWith('data:')) return imageUrl;
    // Already absolute (http/https) — return as-is
    if (imageUrl.startsWith('http')) return imageUrl;
    // Public-folder images (/images/...) — served by the frontend, no prefix needed
    if (imageUrl.startsWith('/images/')) return imageUrl;
    // Uploaded files (/uploads/...) — served by the Express backend
    if (process.env.NODE_ENV === 'production') return imageUrl;
    return `http://localhost:5000${imageUrl}`;
  };

  const formatCR = (cr: number | undefined): string => {
    if (cr === undefined || cr === null) return '—';
    if (cr === 0) return '0';
    if (cr === 0.125) return '1/8';
    if (cr === 0.25) return '1/4';
    if (cr === 0.5) return '1/2';
    return String(Math.round(cr * 100) / 100);
  };

  const getBattleParticipantName = useCallback((participant: BattleParticipant) => {
    return participant.temp_army_name || participant.army_name || `Army #${participant.id}`;
  }, []);

  const getSelectableParticipants = useCallback(() => {
    if (!activeBattle || !activeBattle.participants) return [];
    return activeBattle.participants.filter(p => {
      if ((p.current_troops || 0) <= 0) return false;
      if (p.is_temporary) return user?.role === 'Dungeon Master';
      return p.user_id === user?.id;
    });
  }, [activeBattle, user]);

  const existingFactions = useMemo(() => {
    const names = (activeBattle?.participants || [])
      .map(p => p.team_name)
      .filter((name): name is string => Boolean(name));
    return Array.from(new Set(names));
  }, [activeBattle?.participants]);

  useEffect(() => {
    if (!showAddParticipantModal) return;
    if (existingFactions.length > 0) {
      const teamName = existingFactions[0];
      setNewParticipantTeamMode('existing');
      setNewParticipantTeamSelection(teamName);
      setNewParticipantData(prev => ({ ...prev, team: teamName }));
    } else {
      setNewParticipantTeamMode('new');
      setNewParticipantTeamSelection('');
    }
  }, [showAddParticipantModal, existingFactions]);

  useEffect(() => {
    if (!showInvitePlayersModal) return;
    if (existingFactions.length > 0) {
      const teamName = existingFactions[0];
      setInviteTeamMode('existing');
      setInviteTeamSelection(teamName);
      setInviteTeamName(teamName);
    } else {
      setInviteTeamMode('new');
      setInviteTeamSelection('');
    }
  }, [showInvitePlayersModal, existingFactions]);

  useEffect(() => {
    const handleResize = () => setOverlayViewportWidth(window.innerWidth);
    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // Prime combat HP state from loaded campaign characters so refresh does not briefly show full HP
  // before socket sync/events arrive.
  useEffect(() => {
    if (!currentCampaign?.characters?.length) return;

    const hpMap: Record<number, { current: number; max: number }> = {};
    const limbMap: Record<number, Record<string, number>> = {};

    currentCampaign.characters.forEach((character: any) => {
      hpMap[Number(character.id)] = {
        current: Number(character.hit_points ?? 0),
        max: Number((character as any).hit_points_max ?? character.hit_points ?? 1),
      };

      if ((character as any).limb_health) {
        limbMap[Number(character.id)] = typeof (character as any).limb_health === 'string'
          ? JSON.parse((character as any).limb_health)
          : (character as any).limb_health;
      }
    });

    // Merge defaults under existing combat-synced state (existing keys win).
    setCombatCharacterHp(prev => ({ ...hpMap, ...prev }));
    if (Object.keys(limbMap).length > 0) {
      setCharacterLimbHealth(prev => ({ ...limbMap, ...prev }));
    }

    // Seed resistances from DB so players see them immediately without needing a socket event.
    const resistanceMap: Record<number, { resistances: string[]; immunities: string[]; vulnerabilities: string[] }> = {};
    currentCampaign.characters.forEach((character: any) => {
      const res = character.resistances;
      if (res && (res.resistances?.length > 0 || res.immunities?.length > 0 || res.vulnerabilities?.length > 0)) {
        resistanceMap[Number(character.id)] = res;
      }
    });
    if (Object.keys(resistanceMap).length > 0) {
      setCharacterDataOverrides(prev => {
        const merged: Record<number, Partial<any>> = { ...prev };
        Object.entries(resistanceMap).forEach(([id, res]) => {
          const numId = Number(id);
          // Only set if not already overridden by a more recent socket event
          if (!merged[numId]?.resistances) {
            merged[numId] = { ...merged[numId], resistances: res };
          }
        });
        return merged;
      });
    }

    // Seed proficiencies from DB
    const proficiencyMap: Record<number, { weapons: string[]; armor: string[]; tools: string[]; languages: string[] }> = {};
    currentCampaign.characters.forEach((character: any) => {
      const prof = character.proficiencies;
      if (prof && (prof.weapons?.length > 0 || prof.armor?.length > 0 || prof.tools?.length > 0 || prof.languages?.length > 0)) {
        proficiencyMap[Number(character.id)] = prof;
      }
    });
    if (Object.keys(proficiencyMap).length > 0) {
      setCharacterDataOverrides(prev => {
        const merged: Record<number, Partial<any>> = { ...prev };
        Object.entries(proficiencyMap).forEach(([id, prof]) => {
          const numId = Number(id);
          if (!merged[numId]?.proficiencies) {
            merged[numId] = { ...merged[numId], proficiencies: prof };
          }
        });
        return merged;
      });
    }
  }, [currentCampaign]);

  // ── Darkness overlay ────────────────────────────────────────────────────────
  // Darkness level narrows vision radius (not fog opacity).
  // Players: strong fog + full-clear inner zone + semi-clear partial zone around units.
  // DM:      faded fog + partially revealed zones to visualize unit vision.
  // Two concentric zones per unit:
  //   inner (≤ visionRadius)       → fully lit, see everything
  //   partial (≤ visionRadius × 2)  → dim silhouette zone, see shape but not stats
  //   outer (> visionRadius × 2)   → full darkness
  useEffect(() => {
    const canvas = darknessCanvasRef.current;
    if (!canvas) return;

    const drawDarknessOverlay = () => {
      const rect = canvas.getBoundingClientRect();
      if (rect.width === 0 || rect.height === 0) return;
      // Resize to current CSS dimensions (fixes stale-size bug on resize)
      canvas.width = rect.width;
      canvas.height = rect.height;

      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      ctx.clearRect(0, 0, canvas.width, canvas.height);

      const isDM = user?.role === 'Dungeon Master';
      const BASE_VISION_RADIUS_FT = 30; // 1% ≈ 1ft on the map
      const PLAYER_FOG_OPACITY = 1;
      const DM_FOG_OPACITY = 0.55;
      const darknessRadiusMultiplier = Math.max(0.15, 1 - darknessLevel * 0.85);
      const hasBlindedOwnCombatant = combatants.some(c => {
        if (c.isMonster || Number(c.playerId) !== Number(user?.id)) return false;
        const charConditions = combatConditions[String(c.characterId)] ?? [];
        return charConditions.some(cond => cond.toLowerCase() === 'blinded');
      });
      const shouldApplyVisionOverlay = isDM ? darknessLevel > 0 : (darknessLevel > 0 || hasBlindedOwnCombatant);

      if (!shouldApplyVisionOverlay) return;

      // For players: collect only their own characters.
      // For DM: collect all combatants to preview what units can see.
      const ownCombatantPositions: { x: number; y: number; visionRadius: number }[] = [];
      combatants.forEach(c => {
        const isOwn = !isDM ? (!c.isMonster && Number(c.playerId) === Number(user?.id)) : true;
        if (!isOwn) return;
        const pos = battlePositions[c.characterId];
        if (!pos) return;
        const charConditions = combatConditions[String(c.characterId)] ?? [];
        const isBlinded = charConditions.some(cond => cond.toLowerCase() === 'blinded');
        const blindMultiplier = isBlinded ? 0.25 : 1;
        // Darkvision skill halves the effective darkness penalty
        const hasDarkvision = !c.isMonster && (characterSkills[Number(c.characterId)] ?? []).some(s => s.name?.toLowerCase() === 'darkvision');
        const effectiveDarknessMultiplier = hasDarkvision
          ? Math.max(0.15, 1 - (darknessLevel * 0.5) * 0.85)
          : darknessRadiusMultiplier;
        const visionRadius = BASE_VISION_RADIUS_FT * effectiveDarknessMultiplier * blindMultiplier;
        ownCombatantPositions.push({ x: pos.x, y: pos.y, visionRadius });
      });

      if (isDM) {
        // DM: stable faded veil over entire map
        ctx.fillStyle = `rgba(0, 0, 0, ${DM_FOG_OPACITY})`;
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        // DM: reveal unit-vision areas — full inner zone + dimmed partial zone
        ownCombatantPositions.forEach(({ x, y, visionRadius }) => {
          const cx = (x / 100) * canvas.width;
          const cy = (y / 100) * canvas.height;
          const innerPx = (visionRadius / 100) * canvas.width;
          const outerPx = innerPx * 2; // partial zone extends to 2× vision radius
          const innerStop = innerPx / outerPx; // normalized position of inner edge

          ctx.globalCompositeOperation = 'destination-out';
          ctx.globalAlpha = 1;

          // Gradient: full removal in inner zone, half removal in partial zone, none beyond
          const gradient = ctx.createRadialGradient(cx, cy, 0, cx, cy, outerPx);
          gradient.addColorStop(0,                    'rgba(0, 0, 0, 1)');
          gradient.addColorStop(innerStop * 0.9,      'rgba(0, 0, 0, 1)');  // full lit up to inner edge
          gradient.addColorStop(innerStop,            'rgba(0, 0, 0, 0.5)'); // start partial zone
          gradient.addColorStop(1,                    'rgba(0, 0, 0, 0)');   // edge of partial zone

          ctx.fillStyle = gradient;
          ctx.beginPath();
          ctx.arc(cx, cy, outerPx, 0, Math.PI * 2);
          ctx.fill();
          ctx.globalCompositeOperation = 'source-over';
          ctx.globalAlpha = 1;
        });
      } else {
        // Players: full-black fog with two-zone clearings
        ctx.fillStyle = `rgba(0, 0, 0, ${PLAYER_FOG_OPACITY})`;
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        if (ownCombatantPositions.length > 0) {
          ctx.globalCompositeOperation = 'destination-out';
          ownCombatantPositions.forEach(({ x, y, visionRadius }) => {
            const cx = (x / 100) * canvas.width;
            const cy = (y / 100) * canvas.height;
            const innerPx = (visionRadius / 100) * canvas.width;
            const outerPx = innerPx * 2; // partial zone extends to 2× vision radius
            const innerStop = innerPx / outerPx;

            // Gradient: full removal in inner zone (clear sight), 50% removal in partial zone (dim silhouette)
            const gradient = ctx.createRadialGradient(cx, cy, 0, cx, cy, outerPx);
            gradient.addColorStop(0,                    'rgba(0, 0, 0, 1)');
            gradient.addColorStop(innerStop * 0.85,     'rgba(0, 0, 0, 1)');  // crisp inner edge
            gradient.addColorStop(innerStop,            'rgba(0, 0, 0, 0.5)'); // partial zone (50% fog → silhouette visible)
            gradient.addColorStop(1,                    'rgba(0, 0, 0, 0)');   // fade to full dark

            ctx.fillStyle = gradient;
            ctx.beginPath();
            ctx.arc(cx, cy, outerPx, 0, Math.PI * 2);
            ctx.fill();
          });
          ctx.globalCompositeOperation = 'source-over';
        }
      }
    };

    drawDarknessOverlay();

    // Re-draw whenever the canvas element is resized (fixes multi-screen / panel-resize bug)
    const observer = new ResizeObserver(() => drawDarknessOverlay());
    observer.observe(canvas);
    return () => observer.disconnect();
  }, [darknessLevel, battlePositions, combatants, combatConditions, user, characterSkills]);

  // ── Battlefield darkness overlay (army/mass-combat tab) ─────────────────────
  // Same two-zone logic as combat: inner=fully lit, partial=silhouette zone, outer=full dark.
  // Army vision base radius ≈ 150ft. 1% of map ≈ BATTLEFIELD_FEET_PER_PERCENT ft.
  useEffect(() => {
    const canvas = battlefieldDarknessCanvasRef.current;
    if (!canvas || !activeBattle || darknessLevel <= 0) {
      // Clear canvas when not needed
      if (canvas) {
        const ctx = canvas.getContext('2d');
        if (ctx) ctx.clearRect(0, 0, canvas.width, canvas.height);
      }
      return;
    }

    const BASE_ARMY_VISION_RADIUS_PCT = 150 / BATTLEFIELD_FEET_PER_PERCENT; // ≈22.5%
    const isDM = user?.role === 'Dungeon Master';

    const drawBattlefieldOverlay = () => {
      const rect = canvas.getBoundingClientRect();
      if (rect.width === 0 || rect.height === 0) return;
      canvas.width = rect.width;
      canvas.height = rect.height;

      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      ctx.clearRect(0, 0, canvas.width, canvas.height);

      const PLAYER_FOG_OPACITY = isDM ? 0.55 : 1;

      // Collect observer armies: DM sees via all armies, player sees via own armies
      const observers: { x: number; y: number; visionRadius: number }[] = [];
      (activeBattle.participants ?? []).forEach(p => {
        const isOwn = isDM || p.user_id === user?.id;
        if (!isOwn) return;
        const x = p.position_x ?? 50;
        const y = p.position_y ?? 50;
        observers.push({ x, y, visionRadius: BASE_ARMY_VISION_RADIUS_PCT });
      });

      ctx.fillStyle = `rgba(0, 0, 0, ${PLAYER_FOG_OPACITY})`;
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      if (observers.length > 0) {
        ctx.globalCompositeOperation = 'destination-out';
        observers.forEach(({ x, y, visionRadius }) => {
          const cx = (x / 100) * canvas.width;
          const cy = (y / 100) * canvas.height;
          const innerPx = (visionRadius / 100) * canvas.width;
          const outerPx = innerPx * 2;
          const innerStop = innerPx / outerPx;

          const gradient = ctx.createRadialGradient(cx, cy, 0, cx, cy, outerPx);
          gradient.addColorStop(0,               'rgba(0, 0, 0, 1)');
          gradient.addColorStop(innerStop * 0.85,'rgba(0, 0, 0, 1)');
          gradient.addColorStop(innerStop,       'rgba(0, 0, 0, 0.5)');
          gradient.addColorStop(1,               'rgba(0, 0, 0, 0)');

          ctx.fillStyle = gradient;
          ctx.beginPath();
          ctx.arc(cx, cy, outerPx, 0, Math.PI * 2);
          ctx.fill();
        });
        ctx.globalCompositeOperation = 'source-over';
      }
    };

    drawBattlefieldOverlay();

    const observer = new ResizeObserver(() => drawBattlefieldOverlay());
    observer.observe(canvas);
    return () => observer.disconnect();
  }, [darknessLevel, activeBattle, user]);

  const shouldUseSingleOverlayPanel = (() => {
    if (!overlayViewportWidth) return false;
    const overlapSafetyBuffer = 96;
    const panelWidthTwo = Math.min(850, 0.48 * overlayViewportWidth);
    const halfSpacing = 0.5 * overlayViewportWidth - overlapSafetyBuffer;
    if (panelWidthTwo > halfSpacing) return true;
    const panelWidthThree = Math.min(700, 0.35 * overlayViewportWidth);
    const thirdSpacing = 0.3 * overlayViewportWidth - overlapSafetyBuffer;
    return panelWidthThree > thirdSpacing;
  })();

  const toggleOverlayPanel = (key: 'participants' | 'selection' | 'resolution') => {
    setOverlayLastOpened(key);
    if (shouldUseSingleOverlayPanel) {
      if (key === 'participants') {
        setShowBattlefieldParticipants(prev => {
          const next = !prev;
          if (next) {
            setShowGoalSelectionModal(false);
            setShowGoalResolutionModal(false);
          }
          return next;
        });
        return;
      }
      if (key === 'selection') {
        setShowGoalSelectionModal(prev => {
          const next = !prev;
          if (next) {
            setShowBattlefieldParticipants(false);
            setShowGoalResolutionModal(false);
          }
          return next;
        });
        return;
      }
      setShowGoalResolutionModal(prev => {
        const next = !prev;
        if (next) {
          setShowBattlefieldParticipants(false);
          setShowGoalSelectionModal(false);
        }
        return next;
      });
      return;
    }

    if (key === 'participants') {
      setShowBattlefieldParticipants(prev => !prev);
      return;
    }
    if (key === 'selection') {
      setShowGoalSelectionModal(prev => {
        const next = !prev;
        if (next) setShowGoalResolutionModal(false);
        return next;
      });
      return;
    }
    setShowGoalResolutionModal(prev => {
      const next = !prev;
      if (next) setShowGoalSelectionModal(false);
      return next;
    });
  };


  // Helper functions for category-specific options
  const HORSE_ARMOR_SUBCATEGORIES = ['Horse Head', 'Horse Feet', 'Horse Body'];

  const getSubcategoryOptions = (category: string) => {
    switch (category) {
      case 'Armor':
        return ['Light Armor', 'Medium Armor', 'Heavy Armor', 'Shield', 'Helmet', 'Boots', 'Horse Head', 'Horse Feet', 'Horse Body'];
      case 'Weapon':
        return ['Simple Melee', 'Martial Melee', 'Simple Ranged', 'Martial Ranged'];
      case 'Tool':
        return ['Artisan\'s Tools', 'Gaming Set', 'Kit', 'Musical Instrument', 'Thieves\' Tools', 'Navigator\'s Tools', 'Herbalism Kit', 'Disguise Kit', 'Forgery Kit', 'Poisoner\'s Kit', 'Other Tools'];
      case 'General':
        return ['Adventuring Gear', 'Container', 'Food & Drink', 'Trade Goods'];
      case 'Magic Item':
        return ['Wondrous Item', 'Potion', 'Scroll', 'Ring', 'Rod', 'Staff', 'Wand'];
      case 'Consumable':
        return ['Potion', 'Food', 'Ammunition', 'Other'];
      default:
        return [];
    }
  };

