  // Helper: compute per-limb max HP from a character's BASE HP (not normalized — limbs can sum > baseHP)
  // Formula: Head 25%+CON, Torso 100%+CON (max 200%), Arms 15%+CON, Legs 40%+CON — each +1 CON = +10%
  const calcCharacterLimbHealthMax = (baseHP: number, con: number): Record<string, number> => {
    const conMod = Math.floor((con - 10) / 2);
    const conBonus = Math.max(0, conMod * 0.1);
    return {
      head:      Math.floor(baseHP * Math.min(1.0, 0.25 + conBonus)),
      chest:     Math.floor(baseHP * Math.min(2.0, 1.0 + conBonus)),
      left_arm:  Math.floor(baseHP * Math.min(1.0, 0.15 + conBonus)),
      right_arm: Math.floor(baseHP * Math.min(1.0, 0.15 + conBonus)),
      left_leg:  Math.floor(baseHP * Math.min(1.0, 0.40 + conBonus)),
      right_leg: Math.floor(baseHP * Math.min(1.0, 0.40 + conBonus)),
    };
  };

  // Helper function to determine if user can view all tabs for the selected character
  const canViewAllTabs = useCallback((characterId: number): boolean => {
    if (!user || !currentCampaign) return false;
    
    // Dungeon Master can see everything
    if (user.role === 'Dungeon Master') return true;
    
    // Players can only see full details of their own character
    return currentCampaign.userCharacter?.id === characterId;
  }, [user, currentCampaign]);

  // Helper function to check if companion tab should be visible
  const shouldShowCompanionTab = useCallback((character: any): boolean => {
    if (character.class !== 'Primal Bond') return false;
    
    const beast = characterBeasts[character.id];
    if (!beast) return false;
    
    const level = character.level;
    const beastType = beast.beast_type;
    
    // Agile Hunter (Cheetah/Leopard) gets beast at level 3
    if (beastType === 'Cheetah' || beastType === 'Leopard') {
      return level >= 3;
    }
    // Packbound (Alpha Wolf/Omega Wolf) gets beast at level 6
    if (beastType === 'AlphaWolf' || beastType === 'OmegaWolf') {
      return level >= 6;
    }
    // Colossal Bond (Elephant/Owlbear) gets beast at level 10
    if (beastType === 'Elephant' || beastType === 'Owlbear') {
      return level >= 10;
    }
    
    return false;
  }, [characterBeasts]);

  const shouldShowShadowsTab = useCallback((character: any): boolean => {
    return character.class === 'Shadow Sovereign';
  }, []);

